// ---------------------------------------------------------------------------
// Detection (pure, exported for testing)
// ---------------------------------------------------------------------------

export interface ToolUseBlock {
  name: string;
  input: Record<string, unknown>;
}

/**
 * Group tool_use blocks by their originating assistant MESSAGE — one array
 * per assistant transcript line — so a genuinely parallel batch (multiple
 * tool_use blocks inside ONE assistant message's content array) is
 * distinguishable from tool calls spread across separate assistant messages
 * of the same logical turn (interleaved with a tool_result round-trip). Only
 * the former is "the same tool block" this detector's Success Criterion 1
 * requires — see the module header for why the latter is out of scope.
 */
export function extractToolUseBlocksByMessage(turnLines: TranscriptLine[]): ToolUseBlock[][] {
  const groups: ToolUseBlock[][] = [];
  for (const line of turnLines) {
    const blocks = blocksForLine(line);
    if (blocks.length > 0) groups.push(blocks);
  }
  return groups;
}

/**
 * tool_use blocks carried by ONE transcript line (empty for any line that is
 * not an assistant message with tool_use content).
 *
 * Shared by `extractToolUseBlocksByMessage` (which FILTERS empty results, so
 * its indices do not correspond to `turnLines`) and by
 * `detectConsumeBeforeMint` (which needs index alignment WITH `turnLines`, so
 * it maps this over every line instead). PR #2418 R1: the two were conflated,
 * and the ordering pass indexed a filtered array as if it were the raw lines.
 */
function blocksForLine(line: TranscriptLine): ToolUseBlock[] {
  // Positive assistant-line check (mirrors transcript.ts's extractAssistantText /
  // extractToolUseNames convention) — an assistant line is identified by EITHER
  // discriminator; only skip when NEITHER matches. Written as an explicit `isAssistantLine`
  // boolean rather than the De Morgan-equivalent `type !== "assistant" && role !== "assistant"`
  // continue-guard so the "OR to identify, not to exclude" intent is unambiguous at a glance
  // (PR #2244 R1).
  const isAssistantLine = line.type === "assistant" || line.message?.role === "assistant";
  if (!isAssistantLine) return [];
  const content = line.message?.content;
  if (!Array.isArray(content)) return [];
  const blocks: ToolUseBlock[] = [];
  for (const block of content as Array<Record<string, unknown>>) {
    if (block && block["type"] === "tool_use" && typeof block["name"] === "string") {
      const rawInput = block["input"];
      const input =
        rawInput && typeof rawInput === "object" ? (rawInput as Record<string, unknown>) : {};
      blocks.push({ name: block["name"] as string, input });
    }
  }
  return blocks;
}

export interface BatchMatch {
  mintTool: string;
  consumeTool: string;
  consumeField: string;
  /** First 200 chars of the free-text field's value, for the calibration record. */
  excerpt: string;
  /** The judged field value, bounded and hashed — see {@link judgedCapture}. */
  judged: ArtifactCapture;
}

/**
 * Snapshot the free-text field value this detector judged (mt#3607).
 *
 * `excerpt` above stays exactly 200 chars because it is written to the record
 * as `phrase`, which is the calibration sweep's diversity axis. That truncation
 * is also the whole complaint ask#6932 filed: a reviewer reading 200 characters
 * of a PR body cannot tell whether the pairing was a real
 * mint-then-consume dependence or two independent calls that happened to share
 * a block, and the ask recorded its own confidence as capped by it.
 *
 * The value is ELIDED before capture. This detector's judged input is a
 * tool-call field the agent authored — a PR body, a spec, a memory — and
 * widening what reaches a log is exactly where pasted output starts travelling
 * with it. Eliding costs nothing here because the verdict is CATEGORICAL (the
 * co-occurrence of the two tool categories is the whole signal); the text is
 * evidence for the human reviewer, never an input to the decision.
 */
function judgedCapture(rawValue: string): ArtifactCapture {
  return captureArtifact(elideQuotedContexts(rawValue));
}

/**
 * Detect batched (id-minting, id-consuming) tool-call PAIRS within a turn.
 *
 * For each assistant message's block group (Success Criterion 1's "same tool
 * block"), every ordered pair of DISTINCT blocks (i, j) where block i is an
 * id-minting call and block j is an id-consuming call with a non-empty
 * free-text field produces one match. `i === j` is excluded — a single call
 * that is both categories (`session_pr_create`) cannot reference its own
 * not-yet-existent id, so self-pairing is not a real instance of the failure.
 *
 * Deduplicated per (mintTool, consumeTool, consumeField) triple so a batch
 * with multiple calls of the same shape doesn't produce redundant records.
 *
 * Categorical by design (SC1/SC4): this does NOT attempt to determine
 * whether the consuming call's text ACTUALLY references the minted id — the
 * minted id doesn't exist yet at authoring time, so no string match is
 * possible. Co-occurrence of the two categories in one batch is the whole
 * signal; disambiguating genuine dependence from a legitimate independent
 * pairing is deferred to calibration review (SC4).
 */
export function detectBatchedMintAndConsume(turnLines: TranscriptLine[]): BatchMatch[] {
  const groups = extractToolUseBlocksByMessage(turnLines);
  const seen = new Set<string>();
  const matches: BatchMatch[] = [];

  for (const blocks of groups) {
    for (let i = 0; i < blocks.length; i++) {
      const mintBlock = blocks[i];
      if (!mintBlock || !MINT_TOOL_NAMES.has(mintBlock.name)) continue;

      for (let j = 0; j < blocks.length; j++) {
        if (i === j) continue;
        const consumeBlock = blocks[j];
        if (!consumeBlock) continue;
        const spec = findConsumeSpec(consumeBlock.name);
        if (!spec) continue;

        const rawValue = consumeBlock.input[spec.field];
        if (typeof rawValue !== "string" || rawValue.trim().length === 0) continue;

        const key = `${mintBlock.name}|${consumeBlock.name}|${spec.field}`;
        if (seen.has(key)) continue;
        seen.add(key);

        matches.push({
          mintTool: mintBlock.name,
          consumeTool: consumeBlock.name,
          consumeField: spec.field,
          excerpt: rawValue.slice(0, 200),
          judged: judgedCapture(rawValue),
        });
      }
    }
  }
  return matches;
}

/**
 * A write that referenced a short id BEFORE the call that mints one ran
 * (mt#3340).
 */
export interface ConsumeBeforeMintMatch {
  consumeTool: string;
  consumeField: string;
  /** The id-shaped token the write contained. */
  writtenId: string;
  mintTool: string;
  /** What the later mint actually returned — best-effort, may be undefined. */
  mintedId: string | undefined;
  excerpt: string;
  /** The judged field value, bounded and hashed — see {@link judgedCapture}. */
  judged: ArtifactCapture;
}

/**
 * Detect a CONSUME-before-MINT ordering within one turn (mt#3340).
 *
 * `detectBatchedMintAndConsume` above only pairs calls inside ONE assistant
 * message, excluding cross-message pairs on the rationale that "by the time the
 * second message is composed, the first call's real result is already in hand."
 * That holds only when the MINT precedes the CONSUME. Reversed — a write that
 * names an id, then a mint that produces one — no result can be in hand,
 * because the id does not exist yet. That ordering was entirely unguarded and
 * is what the originating incident did.
 *
 * Unlike the categorical batch pass, this one is EXACT rather than
 * co-occurrence-based, because it runs post-hoc over the transcript where the
 * minted id is present in the later tool_result. The first discriminator is the
 * prior-source check: an id the agent wrote with no prior occurrence anywhere
 * before that write is an id it could not have read in THIS transcript.
 *
 * That check alone is not sufficient, and the calibration data says so
 * (mt#3991). It assumed "a legitimate reference to an EXISTING entity would
 * have a source (a tool result, the user's prompt, an earlier read)" — but an
 * agent routinely cites a task it knows from the task graph, from an injected
 * memory, or from the always-loaded rules, with no occurrence anywhere in the
 * transcript window. Measured over the 10 fires to 2026-08-11: **9 wrote an id
 * that already existed**, by margins from 20 minutes to nearly four months.
 *
 * So the SECOND discriminator — existence — is applied by the caller, which
 * filters these matches through {@link withoutExistingIds}. It is deliberately
 * not applied in here: this function stays pure and synchronous, and the
 * lookup it would need is IO.
 *
 * CROSS-MESSAGE ONLY (PR #2418 R1). The mint must be in a STRICTLY LATER
 * message than the write. A mint in the SAME message is the batch pass's
 * territory — reporting it here too would double-record one event, and within
 * a single parallel batch the block order carries no temporal meaning anyway.
 *
 * ID FAMILIES: short ids only (`mt#`/`ask#`/`mem#`). Session uuids and PR
 * numbers are deliberately out of scope — a bare `#1234` is ambiguous with
 * issue refs, and uuids don't appear in written prose the way short ids do.
 *
 * @param turnLines the assistant turn, in order
 * @param priorText serialized transcript content preceding the turn
 */
export function detectConsumeBeforeMint(
  turnLines: TranscriptLine[],
  priorText: string
): ConsumeBeforeMintMatch[] {
  const matches: ConsumeBeforeMintMatch[] = [];
  const seen = new Set<string>();

  // Index-ALIGNED with turnLines (one entry per line, empty where a line
  // carries no tool_use) — NOT extractToolUseBlocksByMessage, whose filtering
  // makes its indices unusable for "which line am I on?".
  const blocksByLine: ToolUseBlock[][] = turnLines.map(blocksForLine);

  // Text seen so far, line by line, so "did this id have a source?" is
  // evaluated as of the moment of the write — not against the whole turn.
  let seenSoFar = priorText;

  for (let li = 0; li < turnLines.length; li++) {
    for (const block of blocksByLine[li] ?? []) {
      const spec = findConsumeSpec(block.name);
      if (!spec) continue;
      const rawValue = block.input[spec.field];
      if (typeof rawValue !== "string" || rawValue.trim().length === 0) continue;

      const tokens = rawValue.match(ID_TOKEN_RE);
      if (!tokens) continue;

      for (const token of new Set(tokens)) {
        // A token the agent could have READ is not a construction.
        if (seenSoFar.includes(token)) continue;

        const family = MINT_FAMILY_SPECS.find((f) => token.startsWith(f.prefix));
        if (!family) continue;

        const laterMint = findLaterMint(blocksByLine, li, family);
        if (!laterMint) continue;

        const mintedId = extractMintedId(turnLines, laterMint.name, family);
        // A write that named the id the mint actually returned is impossible to
        // author honestly, but if it somehow matches there is nothing to warn about.
        if (mintedId !== undefined && mintedId === token) continue;

        const key = `${block.name}|${spec.field}|${token}`;
        if (seen.has(key)) continue;
        seen.add(key);

        matches.push({
          consumeTool: block.name,
          consumeField: spec.field,
          writtenId: token,
          mintTool: laterMint.name,
          mintedId,
          excerpt: rawValue.slice(0, 200),
          judged: judgedCapture(rawValue),
        });
      }
    }

    // EVERY line becomes a source once passed — including tool_result lines,
    // which is exactly where a legitimately-read id comes from (R1: these were
    // skipped entirely, so an id returned earlier in the same turn looked
    // sourceless).
    seenSoFar += JSON.stringify(turnLines[li] ?? "");
  }

  return matches;
}

/**
 * Drop matches whose written id ALREADY EXISTED — the existence discriminator
 * (mt#3991). Pure: the caller supplies the set, so this is testable without
 * reaching a database.
 *
 * `existing` of `null` means the lookup could not run. That case must keep every
 * match — **fail toward firing**. A detector that goes quiet when its dependency
 * is unavailable is indistinguishable from a dead one (ADR-032), and this file's
 * whole family exists because silent-when-broken is the failure mode that costs
 * weeks to notice. Reporting a false positive is recoverable; reporting nothing
 * is not.
 */
export function withoutExistingIds(
  matches: ConsumeBeforeMintMatch[],
  existing: ReadonlySet<string> | null
): ConsumeBeforeMintMatch[] {
  if (existing === null) return matches;
  return matches.filter((m) => !existing.has(m.writtenId));
}

/**
 * Which of `ids` name a task that exists. Returns `null` on ANY failure — see
 * {@link withoutExistingIds} for why null must not be read as "none exist".
 *
 * ONE query over the distinct ids rather than a lookup per id: this runs on
 * every Stop event, and the id count per turn is small (typically one) but the
 * round trips are not free.
 *
 * SCOPE: `mt#` only. The detector also recognizes `ask#` and `mem#`, whose short
 * ids live in different tables; every fire in the mt#3991 calibration window was
 * `mt#`, so those families keep their prior behavior rather than getting an
 * existence check written against no evidence. Widening is a follow-on, not a
 * silent extension.
 */
export async function resolveExistingTaskIds(
  ids: readonly string[]
): Promise<ReadonlySet<string> | null> {
  const taskIds = [...new Set(ids.filter((id) => id.startsWith("mt#")))];
  if (taskIds.length === 0) return new Set();

  try {
    const bootstrap = await ensureHookDomainBootstrap();
    if (!bootstrap.ok) return null;

    const { resolvePersistenceProviderOrError } = await import(
      "../../packages/domain/src/persistence/factory"
    );
    const resolution = await resolvePersistenceProviderOrError();
    if (!resolution.ok) return null;

    const provider = resolution.provider;
    if (!provider.capabilities.sql || typeof provider.getDatabaseConnection !== "function") {
      return null;
    }
    const db = await (provider as SqlCapablePersistenceProvider).getDatabaseConnection();
    if (!db) return null;

    const { sql } = await import("drizzle-orm");
    const rows = await db.execute(sql`select id from tasks where id in ${taskIds}`);
    const found = Array.isArray(rows) ? rows : ((rows as { rows?: unknown[] }).rows ?? []);
    return new Set(
      found
        .map((r) => (r as { id?: unknown }).id)
        .filter((id): id is string => typeof id === "string")
    );
  } catch {
    // Deliberate: every failure shape collapses to "could not check", which the
    // caller renders as "fire anyway". Rethrowing would take the whole Stop
    // hook down over a detector's optional refinement.
    return null;
  }
}

/** First mint of `family` in a STRICTLY LATER line than `afterLineIndex`. */
function findLaterMint(
  blocksByLine: ToolUseBlock[][],
  afterLineIndex: number,
  family: MintFamilySpec
): ToolUseBlock | undefined {
  for (let li = afterLineIndex + 1; li < blocksByLine.length; li++) {
    for (const block of blocksByLine[li] ?? []) {
      if (family.names.includes(block.name)) return block;
    }
  }
  return undefined;
}

/** Best-effort: pull the id a minting call actually returned. */
function extractMintedId(
  turnLines: TranscriptLine[],
  toolName: string,
  family: MintFamilySpec
): string | undefined {
  for (const field of family.idFields) {
    try {
      const created = findCreatedResourceIds(turnLines, toolName, field);
      const hit = created.find((c) => c.createdId !== undefined);
      if (hit?.createdId) return hit.createdId;
    } catch {
      // Best-effort only — a match never depends on this.
    }
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Calibration logging
// ---------------------------------------------------------------------------

function appendCalibrationRecord(cwd: string, record: Record<string, unknown>): void {
  try {
    // mt#2710: resolve the actual repo ROOT, not the raw shell cwd — `cwd` is
    // routinely a repo subdirectory, and a bare `resolve(cwd, ...)` would
    // scatter this calibration log into a stray subdirectory `.minsky/`.
    const logPath = resolve(findRepoRoot(cwd), CALIBRATION_LOG);
    const dir = dirname(logPath);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }
    appendFileSync(logPath, `${JSON.stringify(record)}\n`, "utf-8");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    process.stderr.write(
      `[constructed-identifier-batch-detector] Failed to write calibration log: ${msg}\n`
    );
  }
}

// ---------------------------------------------------------------------------
// Injection text (gated by INJECTION_ENABLED; SC2 — names the specific
// minting + consuming calls and states the rule)
// ---------------------------------------------------------------------------

export function buildReminder(matches: BatchMatch[]): string {
  const lines = matches
    .map(
      (m) =>
        `  - \`${m.mintTool}\` (mints an id) batched with \`${m.consumeTool}\`'s \`${m.consumeField}\` field: "${m.excerpt}"`
    )
    .join("\n");

  return [
    "[constructed-identifier-batch-detector] Batched dependent tool call detected (mt#3125).",
    "",
    "The prior assistant turn batched an id-MINTING tool call together with a call whose",
    "free-text input is likely to reference that id, in the SAME parallel tool-call batch.",
    "Step N+1 cannot know step N's minted id until step N's real result is read — a batched",
    "dependent chain forces guessing the id (mem#511; CLAUDE.md §Sequence Dependent Tool Calls).",
    "",
    "Matched pairs:",
    lines,
    "",
    "Required: read the minting call's real result THIS turn, then write the consuming",
    "call's free text in the NEXT turn. Never construct/guess an id (taskId, sessionId,",
    "PR number, ask uuid, memory id) before the minting call returns it.",
    "",
    "If the two calls are genuinely INDEPENDENT (the consuming call's text does not",
    "reference the minted id), this is a false positive — say so rather than complying.",
    // Override advertisement removed (mt#4002) — see `guard-feedback-authoring.mdc`.
    // The legitimate-halt branch it was attached to is kept: that IS part of the
    // advisory shape; naming the env var is not.
  ].join("\n");
}

/**
 * Reminder for the consume-before-mint pass (mt#3340). Distinct text from
 * `buildReminder` because the failure is a different shape — not "you batched
 * two calls" but "you wrote an id that did not exist yet" — and because this
 * pass is exact, so it can name both the written token and the real id.
 */
export function buildConsumeBeforeMintReminder(matches: ConsumeBeforeMintMatch[]): string {
  const lines = matches
    .map((m) => {
      const actual = m.mintedId ? ` — \`${m.mintTool}\` actually minted \`${m.mintedId}\`` : "";
      return `  - \`${m.consumeTool}\`'s \`${m.consumeField}\` wrote \`${m.writtenId}\` BEFORE \`${m.mintTool}\` ran${actual}: "${m.excerpt}"`;
    })
    .join("\n");

  return [
    "[constructed-identifier-batch-detector] Constructed identifier written before it was minted (mt#3340).",
    "",
    "A write in the prior turn referenced a short id that had no source anywhere earlier in",
    "the transcript, and a call that MINTS that kind of id ran only afterwards. The id could",
    "not have been read — it did not exist yet.",
    "",
    "Matched writes:",
    lines,
    "",
    "Required: mint FIRST, then write the reference using the id the minting call returned.",
    "Writing a reference and repairing it after the fact only works if you remember to — and",
    "in a source file the wrong id ships and is read as fact (mem#511; CLAUDE.md §Sequence",
    "Dependent Tool Calls).",
    "",
    "If the id was legitimately known from outside this transcript, say so rather",
    "than complying.",
    // Override advertisement removed (mt#4002) — see `guard-feedback-authoring.mdc`.
  ].join("\n");
}

/**
 * Worst-case render for the registry's `renderProbe` (mt#4002).
 *
 * This guard has TWO renderers for its two passes, so the probe returns the
 * LARGER — measuring only one would bound only one, which is the single-axis
 * under-posing `guard-feedback-authoring.mdc` warns about.
 *
 * **Growth-shaped, count axis NOT capped:** both renderers emit one line per
 * match with no `…and N more` bound. Posed at a representative saturation; the
 * cap is the preferred fix and belongs to this guard's owner.
 *
 * The casts are deliberate and measurement-only: both renderers read a handful
 * of string fields and never touch `judged`, so constructing a full
 * `ArtifactCapture` here would add coupling that buys the measurement nothing.
 */
export function renderWorstCase(): string {
  const excerpt = "x".repeat(120);
  const batch = buildReminder(
    Array.from(
      { length: 5 },
      () =>
        ({
          mintTool: "mcp__minsky__tasks_create",
          consumeTool: "mcp__minsky__session_pr_create",
          consumeField: "body",
          excerpt,
        }) as BatchMatch
    )
  );
  const consumeBeforeMint = buildConsumeBeforeMintReminder(
    Array.from(
      { length: 5 },
      () =>
        ({
          consumeTool: "mcp__minsky__session_pr_create",
          consumeField: "body",
          writtenId: "mt#9999",
          mintTool: "mcp__minsky__tasks_create",
          mintedId: "mt#1234",
          excerpt,
        }) as ConsumeBeforeMintMatch
    )
  );
  return batch.length >= consumeBeforeMint.length ? batch : consumeBeforeMint;
}

// ---------------------------------------------------------------------------
// Dispatcher-compatible pure function (ADR-028 D1/D2 — mt#2652 Phase 2a)
// ---------------------------------------------------------------------------

/**
 * Guard-dispatcher entry point. Mirrors `main()`'s orchestration but returns
 * a `GuardOutcome` instead of writing to stdout/`process.exit`. Reuses
 * `ctx.transcriptLines` (D6) instead of re-parsing the transcript itself.
 * Calibration is logged unconditionally on a match; `additionalContext` is
 * gated behind `INJECTION_ENABLED` (false — calibration-first, mt#3125 SC3).
 */
// Async since mt#3991: the existence discriminator needs a database lookup.
// `GuardRegistration.run` already accepts `GuardRunResult | Promise<...>`
// (registry.ts), and the sibling `duplicate-signature-scan` is async for the
// same reason — this is the established shape for a guard that queries.
export async function run(
  input: ClaudeHookInput,
  ctx: DispatchContext
): Promise<GuardOutcome | null> {
  const overrideVal = process.env[OVERRIDE_ENV_VAR];
  const isOverride =
    overrideVal === "1" ||
    overrideVal?.toLowerCase() === "true" ||
    overrideVal?.toLowerCase() === "yes";

  if (isOverride) {
    return {
      auditLines: [
        `[constructed-identifier-batch-detector] OVERRIDE: ack=${overrideVal} session=${input.session_id ?? "unknown"} ts=${new Date().toISOString()}\n`,
      ],
    };
  }

  if (!input.transcript_path) return null;
  const lines = ctx.transcriptLines;
  if (lines.length === 0) return null;

  let matches: BatchMatch[];
  let orderMatches: ConsumeBeforeMintMatch[];
  try {
    const turnLines = extractLastAssistantTurn(lines, ctx.recordedAnchor);
    if (turnLines.length === 0) return null;
    matches = detectBatchedMintAndConsume(turnLines);
    orderMatches = detectConsumeBeforeMint(turnLines, priorTextFor(lines, turnLines));
  } catch (err) {
    process.stderr.write(
      `[constructed-identifier-batch-detector] Detection error: ${err instanceof Error ? err.message : String(err)}\n`
    );
    return null;
  }

  // Existence discriminator (mt#3991) — applied AFTER detection so the lookup
  // covers only ids that actually produced a candidate, and so a lookup failure
  // cannot suppress the batch pass beside it.
  orderMatches = withoutExistingIds(
    orderMatches,
    await resolveExistingTaskIds(orderMatches.map((m) => m.writtenId))
  );

  if (matches.length === 0 && orderMatches.length === 0) return null;

  const outcome: GuardOutcome = {
    calibration: {
      timestamp: new Date().toISOString(),
      session_id: input.session_id,
      injection_enabled: INJECTION_ENABLED,
      [CAPTURE_SCHEMA_FIELD]: CAPTURE_SCHEMA_VERSION,
      // "matches"-shape family (mirrors retrospective-trigger / ask-routing-deferral /
      // pre-narration — see src/domain/calibration/calibration-sweep.ts's fallback
      // parse branch). `category` is the (mintTool, consumeTool) pair label the
      // shared diversity-extraction reads; `phrase` is the excerpt. mintTool/
      // consumeTool/consumeField are carried as extra context for full audit
      // fidelity, not consulted by the shared sweep parser.
      matches: [...batchRecords(matches), ...orderRecords(orderMatches)],
    },
  };

  if (INJECTION_ENABLED) {
    const parts: string[] = [];
    if (matches.length > 0) parts.push(buildReminder(matches));
    if (orderMatches.length > 0) parts.push(buildConsumeBeforeMintReminder(orderMatches));
    outcome.additionalContext = parts.join("\n\n");
  }

  return outcome;
}

/**
 * Serialized transcript content preceding the turn, for the
 * consume-before-mint pass's "did this id have a source?" check.
 * `extractLastAssistantTurn` returns a contiguous suffix, so the prefix is
 * everything before it.
 */
function priorTextFor(lines: TranscriptLine[], turnLines: TranscriptLine[]): string {
  const prefix = lines.slice(0, Math.max(0, lines.length - turnLines.length));
  return prefix.map((l) => JSON.stringify(l)).join("");
}

/** Calibration records for the batch pass. */
function batchRecords(matches: BatchMatch[]): Array<Record<string, unknown>> {
  return matches.map((m) => ({
    category: `${m.mintTool}+${m.consumeTool}`,
    // mt#3781: `phrase` is the sweep's diversity axis. It used to hold
    // `m.excerpt` — a 200-char prefix of the judged field value — so no two
    // fires were ever byte-equal and the diversity gate was satisfied by
    // construction, i.e. inert. This detector is CATEGORICAL: what makes two
    // fires "the same shape" is the (mint, consume, field) triple, which is
    // also the key it already dedupes on. The text is not lost — mt#3607's
    // `judged` capture below carries it, bounded and hashed.
    phrase: `${m.mintTool}|${m.consumeTool}|${m.consumeField}`,
    mintTool: m.mintTool,
    consumeTool: m.consumeTool,
    consumeField: m.consumeField,
    judged: m.judged,
  }));
}

/** Calibration records for the consume-before-mint pass (mt#3340). */
function orderRecords(matches: ConsumeBeforeMintMatch[]): Array<Record<string, unknown>> {
  return matches.map((m) => ({
    category: `consume-before-mint:${m.consumeTool}+${m.mintTool}`,
    // mt#3781, same reasoning as `batchRecords` above. This pass's dedupe key is
    // (consumeTool, field, token), and the written id IS the distinguishing
    // shape here — two writes naming the same id are one pattern, not two.
    phrase: `${m.consumeTool}|${m.consumeField}|${m.writtenId}`,
    consumeTool: m.consumeTool,
    consumeField: m.consumeField,
    writtenId: m.writtenId,
    mintTool: m.mintTool,
    mintedId: m.mintedId ?? null,
    judged: m.judged,
  }));
}

// ---------------------------------------------------------------------------
// Entrypoint
// ---------------------------------------------------------------------------

export async function main(): Promise<void> {
  const overrideVal = process.env[OVERRIDE_ENV_VAR];
  const isOverride =
    overrideVal === "1" ||
    overrideVal?.toLowerCase() === "true" ||
    overrideVal?.toLowerCase() === "yes";

  let input: ClaudeHookInput;
  try {
    input = await readInput<ClaudeHookInput>();
  } catch {
    process.exit(0);
  }

  if (isOverride) {
    const ts = new Date().toISOString();
    process.stdout.write(
      `[constructed-identifier-batch-detector] OVERRIDE: ack=${overrideVal} session=${input.session_id ?? "unknown"} ts=${ts}\n`
    );
    process.exit(0);
  }

  const transcriptPath = input.transcript_path;
  if (!transcriptPath) {
    process.exit(0);
  }

  let lines: TranscriptLine[];
  try {
    lines = resolveParentTranscriptLinesForPath(transcriptPath, input.agent_id);
  } catch (err) {
    console.error(
      `[constructed-identifier-batch-detector] Failed to read transcript: ${getLoggableErrorSummary(err)}`
    );
    process.exit(0);
  }

  if (lines.length === 0) {
    process.exit(0);
  }

  let matches: BatchMatch[];
  let orderMatches: ConsumeBeforeMintMatch[];
  try {
    const turnLines = extractLastAssistantTurn(lines);
    if (turnLines.length === 0) {
      process.exit(0);
    }
    matches = detectBatchedMintAndConsume(turnLines);
    orderMatches = detectConsumeBeforeMint(turnLines, priorTextFor(lines, turnLines));
  } catch (err) {
    console.error(
      `[constructed-identifier-batch-detector] Detection error: ${getLoggableErrorSummary(err)}`
    );
    process.exit(0);
  }

  // Existence discriminator (mt#3991) — see the guard path above.
  orderMatches = withoutExistingIds(
    orderMatches,
    await resolveExistingTaskIds(orderMatches.map((m) => m.writtenId))
  );

  if (matches.length === 0 && orderMatches.length === 0) {
    process.exit(0);
  }

  // Calibration record (always — this is the v1 product, mirroring
  // causal-premise-detector / ask-routing-deferral-detector).
  appendCalibrationRecord(input.cwd, {
    timestamp: new Date().toISOString(),
    session_id: input.session_id,
    injection_enabled: INJECTION_ENABLED,
    [CAPTURE_SCHEMA_FIELD]: CAPTURE_SCHEMA_VERSION,
    matches: [...batchRecords(matches), ...orderRecords(orderMatches)],
  });

  // Calibration-first: inject only when the gate is flipped on.
  if (!INJECTION_ENABLED) {
    process.exit(0);
  }

  const parts: string[] = [];
  if (matches.length > 0) parts.push(buildReminder(matches));
  if (orderMatches.length > 0) parts.push(buildConsumeBeforeMintReminder(orderMatches));

  const output: HookOutput = {
    hookSpecificOutput: {
      hookEventName: "UserPromptSubmit",
      additionalContext: parts.join("\n\n"),
    },
  };
  process.stdout.write(JSON.stringify(output));
  process.exit(0);
}

if (import.meta.main) {
  main();
}
